// Polyfork から取得した GLB を base64 で埋め込み(file:// で開くため)。CC BY 4.0。クレジットは models/CREDITS.md
(function(){window.MODELS=window.MODELS||{};const T=THREE;function mk(b64,cm){const g=new T.Group();const bin=atob(b64),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);new T.GLTFLoader().parse(u.buffer,'',gl=>{const o=gl.scene;const b=new T.Box3().setFromObject(o),s=b.getSize(new T.Vector3());const k=cm/Math.max(s.x,s.y,s.z);o.scale.setScalar(k);const b2=new T.Box3().setFromObject(o),c=b2.getCenter(new T.Vector3());o.position.set(-c.x,-b2.min.y,-c.z);o.traverse(m=>{if(m.isMesh){m.castShadow=m.receiveShadow=true;}});g.add(o);g.userData.ready=true;if(g.userData.onReady)g.userData.onReady();});return g;}
window.MODELS.trash_bag=()=>mk('',40);
window.MODELS.bread=()=>mk('',25);
window.MODELS.cup_takeaway=()=>mk('',15);
window.MODELS.cup_coffee=()=>mk('',10);
window.MODELS.chocolate=()=>mk('',16);
window.MODELS.bottle_sake=()=>mk('',30);
window.MODELS.bottle_potion=()=>mk('',20);
window.MODELS.cart=()=>mk('',105);
window.MODELS.container=(color)=>{const g=mk('',62);if(color){const tint=()=>g.traverse(m=>{if(!m.isMesh)return;m.material=m.material.clone();const h={};m.material.color.getHSL(h);if(h.s>0.5)m.material.color.set('#4a4a4a');else if(h.l>0.5)m.material.color.set(color);});if(g.userData.ready)tint();else g.userData.onReady=tint;}return g;};
})();
